	// ---------------------------------------------------------------- R1: reused packed work

	@Test
	void reusedPackedWorkMakesTheLogIncomplete() {
		StatementPattern resumed = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o"));
		resumed.setDoubleMetricPlanned(LmdbPlanningReadLog.RESUMED_WORK_METRIC, 0.0d);
		StatementPattern fresh = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o"));

		LmdbPlanningReadLog.Log hit = record(() -> LmdbPlanningReadLog.markReusedPackedWork(true, fresh));
		LmdbPlanningReadLog.Log resume = record(() -> LmdbPlanningReadLog.markReusedPackedWork(false, resumed));
		LmdbPlanningReadLog.Log searched = record(() -> LmdbPlanningReadLog.markReusedPackedWork(false, fresh));

		assertAll(
				() -> assertEquals("packed-plan-cache-hit", hit.incompleteReason()),
				() -> assertEquals("packed-checkpoint-resume", resume.incompleteReason(),
						"a resumed search restores a memo priced by an earlier planning, and its budget continues"),
				() -> assertTrue(searched.complete(), "a fresh search makes its reads through the owners"));
	}

