	@Test
	void aLifecycleAdmissionBetweenTheCapturesIsChangedDuringReplay(@TempDir Path directory) throws Exception {
		LmdbOperatorFeedbackStats stats = feedback(directory);
		LogicalLearningKey key = logical("lifecycle-capture");
		LmdbPlanningReadLog.Log log = record(() -> stats.planLifecycleDecision(key, PHYSICAL, APPLICABILITY,
				ENVELOPE));
		long planning = stats.planningRevision();

		LmdbPlanningReadLog.ReplayResult quiet = log.replayAgainstOwners(0.0d, () -> {
		});
		// Another planning admits an entry (and may evict one): the planning revision deliberately ignores it.
		LmdbPlanningReadLog.ReplayResult raced = log.replayAgainstOwners(0.0d,
				() -> stats.planLifecycleDecision(logical("admitted-meanwhile"), PHYSICAL, APPLICABILITY, ENVELOPE));

		assertAll(
				() -> assertEquals(LmdbPlanningReadLog.Verdict.IDENTICAL, quiet.verdict(), quiet.toString()),
				() -> assertEquals(planning, stats.planningRevision(),
						"COVERAGE_PREREQUISITE: an admission does not move the planning revision"),
				() -> assertEquals(LmdbPlanningReadLog.Verdict.CHANGED_DURING_REPLAY, raced.verdict(),
						raced.toString()));
	}

	// ---------------------------------------------------------------- R3: consumers that threshold

	@Test
	void aStructuralBoundsAdmissionIsRecomputedFromTheReplayedEstimateAtEveryTolerance(@TempDir Path directory)
			throws Exception {
		LmdbOperatorFeedbackStats stats = feedback(directory);
		LogicalLearningKey key = logical("bounds-check");
		teach(stats, key, 40, 7L);
		FrontierLearningModel.DimensionEstimate recorded = logicalRead(stats, key).estimate();
		assertNotNull(recorded, "COVERAGE_PREREQUISITE: an estimate is recorded");
		// A structural lower bound just below the estimate's credible upper bound: admitted when recorded.
		double structuralLower = credibleUpper(recorded) * 0.999d;
		assertTrue(LmdbMappedFrontierLearningSession.intersectsMappedBounds(recorded, structuralLower,
				Double.POSITIVE_INFINITY), "COVERAGE_PREREQUISITE: admitted when recorded");
		LmdbPlanningReadLog.Log log = record(() -> {
			FrontierLearningModel.DimensionEstimate estimate = logicalRead(stats, key).estimate();
			LmdbPlanningReadLog.boundsCheck(stats, key, APPLICABILITY, ROWS_ONLY, 10.0d, structuralLower,
					Double.POSITIVE_INFINITY, LmdbMappedFrontierLearningSession.intersectsMappedBounds(estimate,
							structuralLower, Double.POSITIVE_INFINITY));
		});

		// Observations that pull the estimate down a little: within the tolerance, below the structural bound.
		FrontierLearningModel.DimensionEstimate moved = null;
		for (int step = 0; step < 200; step++) {
			teach(stats, key, 1, 6L);
			moved = logicalRead(stats, key).estimate();
			if (!LmdbMappedFrontierLearningSession.intersectsMappedBounds(moved, structuralLower,
					Double.POSITIVE_INFINITY)) {
				break;
			}
		}
		FrontierLearningModel.DimensionEstimate flipped = moved;
		LmdbPlanningReadLog.ReplayResult replayed = log.replayAgainstOwners(TOLERANCE, () -> {
		});

		assertAll(
				() -> assertFalse(LmdbMappedFrontierLearningSession.intersectsMappedBounds(flipped, structuralLower,
						Double.POSITIVE_INFINITY), "COVERAGE_PREREQUISITE: the admission flipped"),
				() -> assertTrue(logDistance(recorded, flipped) <= TOLERANCE,
						"COVERAGE_PREREQUISITE: the model values moved within the tolerance"),
				() -> assertEquals(LmdbPlanningReadLog.Verdict.CHANGED, replayed.verdict(), replayed.toString()),
				() -> assertEquals(LmdbPlanningReadLog.CONSUMER_BOUNDS, replayed.kind(), replayed.toString()));
	}

