	// ---------------------------------------------------------------- R4: low-confidence samples, cuts

	@Test
	void aSampleBelowTheReSampleConfidenceMakesTheLogIncomplete(@TempDir Path directory) {
		LmdbFilterSelectivityStats filters = filters(directory);
		PatternKey pattern = new PatternKey(VF.createIRI("urn:review:p"), 1);
		PatternFilterSampleEstimate small = new PatternFilterSampleEstimate(0.125d, 8L);
		PatternFilterSampleEstimate large = new PatternFilterSampleEstimate(0.125d, 4_096L);
		double threshold = LmdbFilterPassSelection.LIVE_SAMPLE_CONFIDENCE_THRESHOLD;

		LmdbPlanningReadLog.Log lowCached = record(
				() -> LmdbPlanningReadLog.cachedSample(filters, pattern, "f", small, false));
		LmdbPlanningReadLog.Log lowLive = record(() -> {
			LmdbPlanningReadLog.cachedSample(filters, pattern, "f", null, false);
			LmdbPlanningReadLog.liveSample(filters, pattern, "f", small, false);
		});
		LmdbPlanningReadLog.Log confident = record(
				() -> LmdbPlanningReadLog.cachedSample(filters, pattern, "f", large, false));
		LmdbPlanningReadLog.Log none = record(() -> {
			LmdbPlanningReadLog.cachedSample(filters, pattern, "f", null, false);
			LmdbPlanningReadLog.liveSample(filters, pattern, "f", null, false);
		});

		assertAll(
				() -> assertTrue(LmdbFilterPassSelection.sampledFilterPass(small).getConfidenceScore() < threshold,
						"COVERAGE_PREREQUISITE: the small sample is below the re-sample threshold"),
				() -> assertTrue(LmdbFilterPassSelection.sampledFilterPass(large).getConfidenceScore() >= threshold,
						"COVERAGE_PREREQUISITE: the large sample is not"),
				() -> assertEquals("low-confidence-sample", lowCached.incompleteReason()),
				() -> assertEquals("low-confidence-sample", lowLive.incompleteReason()),
				() -> assertTrue(confident.complete(), confident.incompleteReason()),
				() -> assertTrue(none.complete(), "'none' stays replayable: " + none.incompleteReason()));
	}

