	// ---------------------------------------------------------------- R5: self-contained slices

	@Test
	void aSliceComputationIsMarkedForThePerScopeEstimateCaches() {
		boolean[] seen = new boolean[4];
		LmdbPlanningReadLog.Log[] slice = new LmdbPlanningReadLog.Log[1];
		seen[0] = LmdbPlanningReadLog.slicing();
		record(() -> {
			seen[1] = LmdbPlanningReadLog.slicing();
			LmdbPlanningReadLog.recordSlice(() -> seen[2] = LmdbPlanningReadLog.slicing(), slice);
		});
		LmdbPlanningReadLog.recordSlice(() -> seen[3] = LmdbPlanningReadLog.slicing(), slice);

		assertAll(
				() -> assertFalse(seen[0], "outside a planning nothing is sliced"),
				() -> assertFalse(seen[1], "a planning outside a cache computation reads the scope caches"),
				() -> assertTrue(seen[2], "a cache computation inside a planning records a slice"),
				() -> assertTrue(seen[3], "a cache computation outside a planning records a private slice"),
				() -> assertFalse(LmdbPlanningReadLog.slicing(), "the mark ends with the computation"));
	}

	@Test
	void onlyScopeCacheEntriesOlderThanTheOpenSliceAreRechecked() {
		Map<Object, Long> stamps = new HashMap<>();
		boolean[] predates = new boolean[5];
		LmdbPlanningReadLog.Log[] slice = new LmdbPlanningReadLog.Log[1];
		record(() -> {
			LmdbPlanningReadLog.stampSliceEntry(stamps, "before");
			LmdbPlanningReadLog.recordSlice(() -> {
				LmdbPlanningReadLog.stampSliceEntry(stamps, "inside");
				predates[0] = LmdbPlanningReadLog.predatesSlice(stamps.get("before"));
				predates[1] = LmdbPlanningReadLog.predatesSlice(stamps.get("inside"));
				LmdbPlanningReadLog.Log[] inner = new LmdbPlanningReadLog.Log[1];
				LmdbPlanningReadLog.recordSlice(() -> {
					predates[2] = LmdbPlanningReadLog.predatesSlice(stamps.get("inside"));
					return null;
				}, inner);
				predates[3] = LmdbPlanningReadLog.predatesSlice(stamps.get("inside"));
				return null;
			}, slice);
			predates[4] = LmdbPlanningReadLog.predatesSlice(stamps.get("before"));
		});

		assertAll(
				() -> assertFalse(stamps.containsKey("before"), "an entry made outside a slice carries no stamp"),
				() -> assertTrue(predates[0], "an entry from before the slice is rechecked"),
				() -> assertFalse(predates[1], "an entry made inside the slice is not: its reads are in the slice"),
				() -> assertTrue(predates[2], "a nested slice rechecks the outer slice's entries"),
				() -> assertFalse(predates[3], "back in the outer slice its own entries are fresh again"),
				() -> assertFalse(predates[4], "outside every slice nothing is rechecked"));
	}

	// ---------------------------------------------------------------- R6: owners held weakly

	@Test
	void aLogDoesNotKeepItsProviderAliveAndReplaysAsChangedOnceItIsGone(@TempDir Path directory) throws Exception {
		AtomicReference<LmdbOperatorFeedbackStats> holder = new AtomicReference<>(feedback(directory));
		LogicalLearningKey key = logical("weak-owner");
		LmdbPlanningReadLog.Log log = record(() -> {
			holder.get()
					.logicalDimensionDecision(key, APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS,
							ROWS_ONLY, 10.0d);
			holder.get().frontierSemiAntiEstimate(semiAntiFilter(), "EXISTS", "hash");
		});
		WeakReference<LmdbOperatorFeedbackStats> provider = new WeakReference<>(holder.getAndSet(null));
		for (int attempt = 0; attempt < 200 && provider.get() != null; attempt++) {
			System.gc();
			byte[] pressure = new byte[1 << 20];
			pressure[attempt] = 1;
		}

		LmdbPlanningReadLog.ReplayResult replayed = log.replayAgainstOwners(0.0d, () -> {
		});
		assertAll(
				() -> assertTrue(log.count(LmdbPlanningReadLog.LEGACY_GUARD) > 0,
						"COVERAGE_PREREQUISITE: the log holds a guard read"),
				() -> assertNull(provider.get(), "the log kept a superseded provider alive"),
				() -> assertEquals(LmdbPlanningReadLog.Verdict.CHANGED, replayed.verdict(), replayed.toString()),
				() -> assertEquals(LmdbPlanningReadLog.PROVIDERS, replayed.kind(), replayed.toString()));
	}

	// ---------------------------------------------------------------- R7: capture before the identity check

	@Test
	void aProviderSwapAfterTheFirstStepIsNeverIdentical(@TempDir Path directory) throws Exception {
		LmdbOperatorFeedbackStats stats = feedback(directory);
		LmdbOperatorFeedbackStats replacement = feedback(directory.resolve("replacement"));
		LmdbPlanningReadLog.Log log = record(() -> logicalRead(stats, logical("swap")));
		AtomicReference<LmdbOperatorFeedbackStats> published = new AtomicReference<>(stats);
		AtomicLong generation = new AtomicLong();

		LmdbPlanningReadLog.ReplayResult swapped = log.replay(0.0d, generation::get,
				() -> new Object[] { published.get(), null, null }, () -> {
					published.set(replacement);
					generation.incrementAndGet();
				}, () -> {
				});

		assertNotEquals(LmdbPlanningReadLog.Verdict.IDENTICAL, swapped.verdict(),
				"a provider replaced between the first two steps of a replay: " + swapped);
	}

