	@Test
	void theReadCapIsATotalOfSixteenReadsPerAllowedKeyGroup() {
		String previous = System.setProperty(LmdbPlanningReadLog.MAX_KEY_GROUPS_PROPERTY, "2");
		try {
			LogicalLearningKey key = logical("read-cap");
			List<LmdbPlanningReadLog.Log> logs = new ArrayList<>();
			for (int reads : new int[] { 2 * LmdbPlanningReadLog.READS_PER_ALLOWED_KEY_GROUP,
					2 * LmdbPlanningReadLog.READS_PER_ALLOWED_KEY_GROUP + 1 }) {
				logs.add(record(() -> {
					for (int read = 0; read < reads; read++) {
						LmdbPlanningReadLog.exactFact(null, key, APPLICABILITY, Double.NaN);
					}
				}));
			}
			assertAll(
					() -> assertTrue(logs.get(0).complete(),
							"one key group may take every read the total allows: " + logs.get(0).incompleteReason()),
					() -> assertEquals("read-cap", logs.get(1).incompleteReason()));
		} finally {
			if (previous == null) {
				System.clearProperty(LmdbPlanningReadLog.MAX_KEY_GROUPS_PROPERTY);
			} else {
				System.setProperty(LmdbPlanningReadLog.MAX_KEY_GROUPS_PROPERTY, previous);
			}
		}
	}

	@Test
	void aOneUlpChangeAtToleranceZeroIsAChange() {
		double value = 12_345.678d;
		double next = Math.nextUp(value);
		double ratio = 0.375d;
		assertAll(
				() -> assertEquals(0.0d, Math.log1p(next) - Math.log1p(value),
						"COVERAGE_PREREQUISITE: log1p maps the adjacent doubles to one value"),
				() -> assertEquals(LmdbPlanningReadLog.CHANGED_OUTCOME,
						LmdbPlanningReadLog.compareModelValue(value, next, 0.0d)),
				() -> assertEquals(LmdbPlanningReadLog.CHANGED_OUTCOME,
						LmdbPlanningReadLog.compareSpread(value, next, 0.0d)),
				() -> assertEquals(LmdbPlanningReadLog.CHANGED_OUTCOME,
						LmdbPlanningReadLog.compareRatio(ratio, Math.nextUp(ratio), 0.0d)),
				() -> assertEquals(LmdbPlanningReadLog.WITHIN_OUTCOME,
						LmdbPlanningReadLog.compareModelValue(value, next, TOLERANCE)));
	}

